-- Function: public.sp_update_platform_organization_details
-- Backup generated on 2026-10-25 20:34:13

CREATE OR REPLACE PROCEDURE public.sp_update_platform_organization_details(IN p_id uuid, IN p_name character varying, IN p_location character varying, IN p_admin_email character varying, IN p_branch_count integer)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_tenant_id UUID;     v_current_branches_count INT;     v_i INT;     v_branch_name VARCHAR;     v_trimmed_email VARCHAR;     v_derived_name VARCHAR;     v_existing_user_id UUID;     v_admin_user_id UUID;     v_current_user_id UUID; BEGIN     UPDATE organizations      SET name = p_name, location = p_location, updated_at = NOW()      WHERE id = p_id;      UPDATE tenants      SET name = p_name, updated_at = NOW()      WHERE id = p_id;      SELECT tenant_id INTO v_tenant_id FROM organizations WHERE id = p_id;     IF v_tenant_id IS NULL THEN         v_tenant_id := p_id;     END IF;      SELECT COUNT(*) INTO v_current_branches_count FROM branches WHERE organization_id = p_id;     IF v_current_branches_count = 0 THEN         FOR v_i IN 1..GREATEST(1, p_branch_count) LOOP             IF v_i = 1 THEN                 v_branch_name := 'Main Campus';             ELSIF v_i = 2 THEN                 v_branch_name := 'Annex Campus';             ELSE                 v_branch_name := 'Campus ' || v_i;             END IF;             INSERT INTO branches (id, tenant_id, organization_id, name, location, is_active)             VALUES (gen_random_uuid(), v_tenant_id, p_id, v_branch_name, COALESCE(p_location, 'Branch Location'), TRUE);         END LOOP;     ELSIF v_current_branches_count < p_branch_count THEN         FOR v_i IN (v_current_branches_count + 1)..p_branch_count LOOP             IF v_i = 2 THEN                 v_branch_name := 'Annex Campus';             ELSE                 v_branch_name := 'Campus ' || v_i;             END IF;             INSERT INTO branches (id, tenant_id, organization_id, name, location, is_active)             VALUES (gen_random_uuid(), v_tenant_id, p_id, v_branch_name, COALESCE(p_location, 'Branch Location'), TRUE);         END LOOP;     END IF;      IF p_admin_email IS NOT NULL AND trim(p_admin_email) <> '' THEN         v_trimmed_email := trim(p_admin_email);         v_derived_name := initcap(split_part(split_part(v_trimmed_email, '@', 1), '.', 1));         IF v_derived_name IS NULL OR v_derived_name = '' THEN             v_derived_name := 'Daycare Director';         END IF;          SELECT id INTO v_existing_user_id          FROM users          WHERE normalized_email = UPPER(v_trimmed_email)          LIMIT 1;          IF v_existing_user_id IS NOT NULL THEN             v_admin_user_id := v_existing_user_id;             UPDATE users              SET is_active = TRUE,                 display_name = COALESCE(NULLIF(TRIM(display_name), ''), v_derived_name),                 updated_at = NOW()              WHERE id = v_admin_user_id;         ELSE             SELECT om.user_id INTO v_current_user_id             FROM organization_memberships om             JOIN users u ON u.id = om.user_id             WHERE om.organization_id = p_id AND om.status = 'Active'             ORDER BY om.created_at             LIMIT 1;              IF v_current_user_id IS NOT NULL THEN                 v_admin_user_id := v_current_user_id;                 UPDATE users                  SET email = v_trimmed_email,                      normalized_email = UPPER(v_trimmed_email),                      display_name = v_derived_name,                     updated_at = NOW()                  WHERE id = v_admin_user_id;             ELSE                 v_admin_user_id := gen_random_uuid();                 INSERT INTO users (id, tenant_id, email, normalized_email, email_confirmed, first_name, last_name, display_name, is_active)                 VALUES (v_admin_user_id, v_tenant_id, v_trimmed_email, UPPER(v_trimmed_email), TRUE, 'Admin', v_derived_name, v_derived_name, TRUE)                 ON CONFLICT (normalized_email) DO UPDATE SET updated_at = NOW();             END IF;         END IF;          DELETE FROM user_organization_roles          WHERE organization_id = p_id AND user_id != v_admin_user_id;                  DELETE FROM organization_memberships          WHERE organization_id = p_id AND user_id != v_admin_user_id;          INSERT INTO organization_memberships (user_id, organization_id, tenant_id, status)         VALUES (v_admin_user_id, p_id, v_tenant_id, 'Active')         ON CONFLICT (user_id, organization_id) DO UPDATE SET status = 'Active', tenant_id = v_tenant_id;          INSERT INTO user_organization_roles (user_id, role_id, organization_id, tenant_id)         SELECT v_admin_user_id, r.id, p_id, v_tenant_id         FROM roles r         WHERE r.tenant_id = v_tenant_id AND r.name IN ('OrganizationOwner', 'OrganizationAdmin')         ON CONFLICT (user_id, role_id, organization_id) DO NOTHING;     END IF; END; $procedure$ ;
